func consume(ctx context.Context, msg Message) error {
    key := "processed:" + msg.ID
    // SetNX:原子地「占坑」。返回 true 表示我抢到了处理权
    ok, err := rdb.SetNX(ctx, key, "1", 24*time.Hour).Result()
    if err != nil {
        return err          // Redis 故障,让消息稍后重投
    }
    if !ok {
        return nil          // 已处理过,幂等跳过(要 ACK 掉,别再重投)
    }
    if err := doBusiness(ctx, msg); err != nil {
        rdb.Del(ctx, key)   // 失败撤销,允许重试
        return err
    }
    return nil
}

