// 用数据库唯一约束做幂等 —— 对「创建」类操作最省事
// 消息表里 msg_id 建唯一索引,重复插入直接被数据库挡下
bool consume(const Message& msg) {
    try {
        // INSERT 带唯一约束。重复的 msg_id 会抛 unique_violation
        db.exec("INSERT INTO processed_msgs(msg_id) VALUES(?)", msg.id);
    } catch (const unique_violation&) {
        return true;        // 已处理过,幂等跳过
    }
    do_business(msg);       // 只有第一次插入成功才会执行到这
    return true;
}
